import type { Metadata } from "next";

import { SITE_NAME } from "@/lib/site";

// Generated by app/opengraph-image.tsx.
const SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "KwanPay — One Wallet. Every Journey. Across Africa.",
};

/**
 * Per-page metadata. Child `openGraph` objects replace the parent's rather
 * than merging, so every page restates the shared Open Graph fields.
 */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  path: string;
}): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: SITE_NAME,
      locale: "en_US",
      title: `${title} — ${SITE_NAME}`,
      description,
      url: path,
      images: [SHARE_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: `${title} — ${SITE_NAME}`,
      description,
      images: [SHARE_IMAGE.url],
    },
  };
}
